package com.bossfightlog;

import java.time.Instant;
import lombok.Value;

/**
 * A completed boss kill. Immutable once the fight has resolved.
 */
@Value
public class BossFight
{
	public static final double SECONDS_PER_TICK = 0.6d;

	String bossName;
	int combatLevel;
	int damageDealt;
	int damageTaken;
	int hits;
	int misses;
	int maxHit;
	/**
	 * Ticks spent actually fighting, with idle gaps already deducted.
	 */
	int durationTicks;
	Instant finishedAt;

	public double getDurationSeconds()
	{
		return durationTicks * SECONDS_PER_TICK;
	}

	/**
	 * Whether this fight lasted long enough for a rate to mean anything. A kill landed inside one
	 * tick has no duration to divide by, so it has damage but no DPS.
	 */
	public boolean isDpsMeasurable()
	{
		return durationTicks > 0;
	}

	public double getDps()
	{
		double seconds = getDurationSeconds();
		return seconds > 0 ? damageDealt / seconds : 0d;
	}

	/**
	 * Share of attempted attacks that landed, in the range 0..1.
	 */
	public double getAccuracy()
	{
		int attempts = hits + misses;
		return attempts > 0 ? (double) hits / attempts : 0d;
	}
}

package com.bossfightlog;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BossFightLogConfig.GROUP)
public interface BossFightLogConfig extends Config
{
	String GROUP = "boss-fight-log";
	String CLEAR_HISTORY = "clearHistory";

	/**
	 * Deliberately far above attack speed. Most weapons swing every four or five ticks, so a
	 * threshold near ten is only two cycles, and two cycles of not attacking is ordinary combat:
	 * stepping out of a hazard, eating, switching prayer.
	 * <p>
	 * The two ways of being wrong are not equally bad. Too low and real fight time is deducted,
	 * inflating DPS invisibly and dragging the comparison baseline with it. Too high and a genuine
	 * bank trip counts as fight time, making one kill look slow, which is obvious on sight. So this
	 * errs high, but not absurdly so: eighteen seconds without a single attack inside one fight is
	 * already long past any mechanic, and short enough that a bank trip still gets caught.
	 */
	@ConfigItem(
		keyName = "idleTimeoutTicks",
		name = "Idle timeout (ticks)",
		description = "Stop the fight timer after this many ticks without attacking, so banking or walking away mid-fight does not count against your DPS. Must stay well above your attack speed: a few missed attacks is still fighting",
		position = 1
	)
	default int idleTimeoutTicks()
	{
		return 30;
	}

	/**
	 * A trigger rather than a setting: enabling it wipes the history and it switches itself back
	 * off. RuneLite shows a confirmation prompt for any item carrying a warning, which is what
	 * makes this safe to sit in the settings panel.
	 */
	@ConfigItem(
		keyName = CLEAR_HISTORY,
		name = "Clear recorded history",
		description = "Deletes every kill recorded for the character you are logged in as",
		warning = "This deletes every kill recorded for this character. A backup is kept in the boss-fight-log folder, but the panel will be emptied.",
		position = 2
	)
	default boolean clearHistory()
	{
		return false;
	}
}

package com.bossfightlog;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * The side panel: session totals on top, then either one card per kill or one row per boss.
 * <p>
 * Rebuilt wholesale whenever the fight list changes. A history holds hundreds of kills rather than
 * millions, so the simplicity is worth more than incremental updates would be.
 */
class BossFightLogPanel extends PluginPanel
{
	private final SummaryPanel summary = new SummaryPanel();
	private final JPanel content = new JPanel();
	private final JLabel allKillsTab = new JLabel("ALL KILLS");
	private final JLabel byBossTab = new JLabel("BY BOSS");
	private final JLabel status = new JLabel();

	private List<BossFight> fights = new ArrayList<>();
	private boolean groupByBoss;

	BossFightLogPanel()
	{
		setLayout(new BorderLayout(0, 4));
		setBorder(new EmptyBorder(6, 6, 6, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildHeader(), BorderLayout.NORTH);
		add(content, BorderLayout.CENTER);

		setFights(Collections.emptyList());
	}

	/**
	 * Replaces the displayed fights. Safe to call from the client thread.
	 */
	void setFights(List<BossFight> fights)
	{
		List<BossFight> snapshot = new ArrayList<>(fights);
		SwingUtilities.invokeLater(() -> {
			this.fights = snapshot;
			rebuild();
		});
	}

	/**
	 * Chooses the view. Used by the preview so the grouped cards can be inspected too; without it
	 * only the flat list is ever rendered, which is how the grouped cards were left behind.
	 */
	void setGroupByBoss(boolean grouped)
	{
		SwingUtilities.invokeLater(() -> {
			this.groupByBoss = grouped;
			rebuild();
		});
	}

	private void rebuild()
	{
		summary.update(fights);
		status.setText(fights.isEmpty()
			? ""
			: fights.size() + " · " + Formats.duration(SummaryPanel.totalSeconds(fights)));
		updateTabStyles();

		content.removeAll();

		if (groupByBoss)
		{
			for (BossGroup group : BossGroup.group(fights))
			{
				content.add(wrap(new GroupCard(group, fights)));
			}
		}
		else
		{
			for (int i = fights.size() - 1; i >= 0; i--)
			{
				BossFight fight = fights.get(i);
				content.add(wrap(new FightCard(fight, BossGroup.dpsTrend(fight, fights))));
			}
		}

		content.revalidate();
		content.repaint();
	}

	private static JPanel wrap(JPanel card)
	{
		JPanel spacer = new JPanel(new BorderLayout());
		spacer.setOpaque(false);
		spacer.setBorder(new EmptyBorder(0, 0, 3, 0));
		spacer.setAlignmentX(Component.LEFT_ALIGNMENT);
		spacer.add(card, BorderLayout.CENTER);
		spacer.setMaximumSize(new Dimension(Integer.MAX_VALUE, spacer.getPreferredSize().height));
		return spacer;
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Boss Fight Log");
		title.setFont(Fonts.bold(14f));
		title.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		status.setFont(Fonts.regular(10f));
		status.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		status.setHorizontalAlignment(SwingConstants.RIGHT);

		titleRow.add(title, BorderLayout.WEST);
		titleRow.add(status, BorderLayout.EAST);

		header.add(titleRow, BorderLayout.NORTH);
		header.add(summary, BorderLayout.CENTER);
		header.add(buildTabs(), BorderLayout.SOUTH);
		return header;
	}

	private JPanel buildTabs()
	{
		JPanel tabs = new JPanel(new GridLayout(1, 2, 1, 0));
		tabs.setBackground(ColorScheme.MEDIUM_GRAY_COLOR.darker());
		tabs.setBorder(new MatteBorder(1, 1, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR.darker()));

		configureTab(allKillsTab, false);
		configureTab(byBossTab, true);

		tabs.add(allKillsTab);
		tabs.add(byBossTab);
		return tabs;
	}

	private void configureTab(JLabel tab, boolean grouped)
	{
		tab.setFont(Fonts.bold(11f));
		tab.setHorizontalAlignment(SwingConstants.CENTER);
		tab.setOpaque(true);
		tab.setCursor(new Cursor(Cursor.HAND_CURSOR));
		tab.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (groupByBoss != grouped)
				{
					groupByBoss = grouped;
					rebuild();
				}
			}
		});
	}

	/**
	 * The selected tab is filled and lit; the other sits flush with the panel behind it, so which
	 * view is showing is legible without reading either label.
	 */
	private void updateTabStyles()
	{
		styleTab(allKillsTab, !groupByBoss);
		styleTab(byBossTab, groupByBoss);
	}

	private static void styleTab(JLabel tab, boolean selected)
	{
		tab.setBackground(selected ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		tab.setForeground(selected ? ColorScheme.TEXT_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
		// The fill and the text colour carry the selection on their own; an underline as well was
		// one marker too many for a two item strip.
		tab.setBorder(new EmptyBorder(6, 0, 6, 0));
	}
}

package com.bossfightlog;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Boss Fight Log",
	description = "Per-kill boss history with DPS, kill times, damage taken and accuracy",
	tags = {"dps", "boss", "kill", "damage", "combat", "pvm", "log"}
)
public class BossFightLogPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private FightTracker fightTracker;

	@Inject
	private FightStore fightStore;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	private final List<BossFight> fights = new ArrayList<>();

	private BossFightLogPanel panel;
	private NavigationButton navButton;

	/**
	 * Character whose history is currently loaded, or null before the first login. History is kept
	 * per character so accounts do not pool their kills.
	 */
	private String loadedCharacter;

	@Override
	protected void startUp() throws Exception
	{
		fights.clear();
		loadedCharacter = null;
		fightTracker.reset();
		fightTracker.setFightListener(this::onFightComplete);

		panel = new BossFightLogPanel();

		BufferedImage icon = ImageUtil.loadImageResource(BossFightLogPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Boss Fight Log")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		log.debug("Boss Fight Log started, panel font: {}", Fonts.describe());
	}

	@Override
	protected void shutDown() throws Exception
	{
		fightTracker.setFightListener(fight -> {
		});
		fightTracker.reset();
		fights.clear();
		loadedCharacter = null;

		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;

		log.debug("Boss Fight Log stopped");
	}

	/**
	 * Handles the settings toggle that wipes this character's history. The toggle is a trigger
	 * rather than a stored preference, so it is switched straight back off once acted on.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BossFightLogConfig.GROUP.equals(event.getGroup())
			|| !BossFightLogConfig.CLEAR_HISTORY.equals(event.getKey())
			|| !Boolean.parseBoolean(event.getNewValue()))
		{
			return;
		}

		configManager.setConfiguration(BossFightLogConfig.GROUP, BossFightLogConfig.CLEAR_HISTORY, false);
		clearFights();
	}

	private void clearFights()
	{
		clientThread.invoke(() -> {
			if (loadedCharacter == null)
			{
				log.debug("Nothing cleared: no character loaded");
				return;
			}

			log.debug("Clearing {} recorded kills for {}", fights.size(), loadedCharacter);
			fights.clear();
			// Copied aside rather than simply overwritten. This is the one action that can destroy
			// a history outright, and a confirmation is little comfort once it has been dismissed.
			fightStore.saveWithBackup(loadedCharacter, fights);
			updatePanel();
		});
	}

	private void onFightComplete(BossFight fight)
	{
		fights.add(fight);

		while (fights.size() > FightStore.MAX_FIGHTS)
		{
			fights.remove(0);
		}

		persist();
		updatePanel();

		log.debug("{} killed in {}s: {} dps, {} damage taken, {}/{} accuracy",
			fight.getBossName(),
			String.format("%.1f", fight.getDurationSeconds()),
			String.format("%.2f", fight.getDps()),
			fight.getDamageTaken(),
			fight.getHits(),
			fight.getHits() + fight.getMisses());
	}

	private void persist()
	{
		if (loadedCharacter != null)
		{
			fightStore.save(loadedCharacter, fights);
		}
	}

	private void updatePanel()
	{
		if (panel != null)
		{
			panel.setFights(fights);
		}
	}

	/**
	 * Loads the history for whichever character is logged in, once their name is available.
	 * <p>
	 * The name is not readable at the moment the game state flips to logged in, so this is driven
	 * from the tick instead of from the state change.
	 */
	private void loadHistoryIfNeeded()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		String name = local.getName();
		if (name == null || name.equals(loadedCharacter))
		{
			return;
		}

		loadedCharacter = name;
		log.debug("Loading fight history for {}", name);

		fightStore.load(name, loaded -> clientThread.invoke(() -> {
			// Anything recorded while the file was being read is kept, and would otherwise be lost
			// to the load overwriting it.
			List<BossFight> merged = new ArrayList<>(FightStore.capped(loaded));
			merged.addAll(fights);

			fights.clear();
			fights.addAll(FightStore.capped(merged));
			updatePanel();

			log.debug("Loaded {} recorded kills for {}", fights.size(), name);
		}));
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		fightTracker.onHitsplatApplied(event);
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		fightTracker.onActorDeath(event);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		fightTracker.onNpcDespawned(event);
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		fightTracker.onNpcChanged(event);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		fightTracker.onGameTick();
		loadHistoryIfNeeded();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			fightTracker.reset();
		}
	}

	@Provides
	BossFightLogConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BossFightLogConfig.class);
	}
}

package com.bossfightlog;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Every recorded kill of one boss, with its aggregates.
 */
class BossGroup
{
	private final String bossName;
	private final int combatLevel;
	private final List<BossFight> fights = new ArrayList<>();

	private int totalTicks;
	private int totalDamage;
	private int totalTaken;
	private int totalHits;
	private int totalAttempts;
	private int bestTicks = Integer.MAX_VALUE;
	private double bestDps;

	private BossGroup(BossFight first)
	{
		this.bossName = first.getBossName();
		this.combatLevel = first.getCombatLevel();
	}

	private void add(BossFight fight)
	{
		fights.add(fight);
		totalTaken += fight.getDamageTaken();
		totalHits += fight.getHits();
		totalAttempts += fight.getHits() + fight.getMisses();
		bestTicks = Math.min(bestTicks, fight.getDurationTicks());

		// A same tick kill has damage but no duration to divide it by. Counting its damage
		// without its time would inflate every rate derived from the pair.
		if (!fight.isDpsMeasurable())
		{
			return;
		}

		totalTicks += fight.getDurationTicks();
		totalDamage += fight.getDamageDealt();
		bestDps = Math.max(bestDps, fight.getDps());
	}

	String getBossName()
	{
		return bossName;
	}

	int getCombatLevel()
	{
		return combatLevel;
	}

	int getKills()
	{
		return fights.size();
	}

	int getDamageTaken()
	{
		return totalTaken;
	}

	double getBestDps()
	{
		return bestDps;
	}

	/**
	 * Kills of this boss, most recent first.
	 */
	List<BossFight> getFightsNewestFirst()
	{
		List<BossFight> reversed = new ArrayList<>(fights);
		java.util.Collections.reverse(reversed);
		return reversed;
	}

	double getAverageSeconds()
	{
		int measured = 0;
		for (BossFight fight : fights)
		{
			if (fight.isDpsMeasurable())
			{
				measured++;
			}
		}
		return measured == 0 ? 0 : totalTicks * BossFight.SECONDS_PER_TICK / measured;
	}

	double getBestSeconds()
	{
		return bestTicks == Integer.MAX_VALUE ? 0 : bestTicks * BossFight.SECONDS_PER_TICK;
	}

	/**
	 * Total damage over total time, so a long kill weighs more than a short one.
	 */
	double getAverageDps()
	{
		double seconds = totalTicks * BossFight.SECONDS_PER_TICK;
		return seconds > 0 ? totalDamage / seconds : 0;
	}

	double getAccuracy()
	{
		return totalAttempts > 0 ? (double) totalHits / totalAttempts : 0;
	}

	/**
	 * Groups kills by boss, ordered by most recently killed first.
	 */
	static List<BossGroup> group(List<BossFight> fights)
	{
		Map<String, BossGroup> byName = new LinkedHashMap<>();
		for (BossFight fight : fights)
		{
			byName.computeIfAbsent(fight.getBossName(), name -> new BossGroup(fight)).add(fight);
		}

		List<BossGroup> groups = new ArrayList<>(byName.values());
		// Insertion order follows first kill; the most recently fought boss is more useful on top.
		groups.sort((a, b) -> Integer.compare(lastIndex(fights, b), lastIndex(fights, a)));
		return groups;
	}

	private static int lastIndex(List<BossFight> fights, BossGroup group)
	{
		for (int i = fights.size() - 1; i >= 0; i--)
		{
			if (fights.get(i).getBossName().equals(group.getBossName()))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * How this kill's DPS compares with the player's other recorded kills of the same boss,
	 * as a signed fraction. Returns null when there is nothing to compare against.
	 */
	static Double dpsTrend(BossFight fight, List<BossFight> all)
	{
		double otherDamageSeconds = 0;
		double otherDamage = 0;
		int others = 0;

		if (!fight.isDpsMeasurable())
		{
			return null;
		}

		for (BossFight other : all)
		{
			if (other == fight || !other.getBossName().equals(fight.getBossName()) || !other.isDpsMeasurable())
			{
				continue;
			}
			otherDamage += other.getDamageDealt();
			otherDamageSeconds += other.getDurationSeconds();
			others++;
		}

		if (others == 0 || otherDamageSeconds <= 0)
		{
			return null;
		}

		double baseline = otherDamage / otherDamageSeconds;
		if (baseline <= 0)
		{
			return null;
		}

		return (fight.getDps() - baseline) / baseline;
	}
}

package com.bossfightlog;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.NPC;

/**
 * Maps NPCs onto the encounter they belong to.
 * <p>
 * Most bosses are an encounter of one. A few are fought as a pair and are recorded as a single
 * kill, because two rows reading half a fight each is not what happened.
 * <p>
 * Wave minigames are represented by their final boss alone, so the fight begins on the first hit
 * against Jad, Zuk or Sol Heredit rather than covering the waves before them.
 */
@Singleton
public class BossRegistry
{
	/**
	 * One tracked fight.
	 */
	static final class Encounter
	{
		private final String name;
		private final Set<String> members;

		private Encounter(String name, Set<String> members)
		{
			this.name = name;
			this.members = members;
		}

		String getName()
		{
			return name;
		}

		/**
		 * Members are the boss itself: the encounter ends once every engaged member has died.
		 */
		boolean isMember(String npcName)
		{
			return npcName != null && members.contains(npcName);
		}
	}

	/**
	 * Bosses fought alone, where the encounter is just the one NPC.
	 */
	private static final String[] SOLO = {
		// God Wars Dungeon
		"General Graardor",
		"K'ril Tsutsaroth",
		"Kree'arra",
		"Commander Zilyana",
		// Slayer
		"Cerberus",
		"Abyssal Sire",
		"Kraken",
		"Thermonuclear smoke devil",
		"Alchemical Hydra",
		"Sarachnis",
		"Araxxor",
		// Wilderness
		"Callisto",
		"Venenatis",
		"Vet'ion",
		"Artio",
		"Spindel",
		"Calvar'ion",
		"Chaos Elemental",
		"Chaos Fanatic",
		"Crazy archaeologist",
		"Deranged archaeologist",
		"Scorpia",
		// Dagannoth Kings, killed and tracked separately
		"Dagannoth Rex",
		"Dagannoth Prime",
		"Dagannoth Supreme",
		// Desert Treasure II
		"Duke Sucellus",
		"The Leviathan",
		"The Whisperer",
		"Vardorvis",
		// Barrows
		"Ahrim the Blighted",
		"Dharok the Wretched",
		"Guthan the Infested",
		"Karil the Tainted",
		"Torag the Corrupted",
		"Verac the Defiled",
		// Perilous Moons
		"Blood Moon",
		"Blue Moon",
		"Eclipse Moon",
		// Wave minigames, final boss only
		"TzTok-Jad",
		"TzKal-Zuk",
		"Sol Heredit",
		// Assorted
		"King Black Dragon",
		"Kalphite Queen",
		"Corporeal Beast",
		"Giant Mole",
		"Obor",
		"Bryophyta",
		"Skotizo",
		"Hespori",
		"Scurrius",
		"The Hueycoatl",
		"Amoxliatl",
		"The Mimic",
		"Shellbane gryphon",
		"Brutus",
		"Demonic Brutus",
		"Mad Angel",
		"Maggot King",
	};

	private final Map<String, Encounter> byNpcName = new HashMap<>();

	public BossRegistry()
	{
		for (String boss : SOLO)
		{
			register(new Encounter(boss, singleton(boss)));
		}

		// Fought as a pair and recorded as one kill.
		register(new Encounter("Grotesque Guardians", names("Dusk", "Dawn")));
		register(new Encounter("Royal Titans", names("Branda the Fire Queen", "Eldric the Ice King")));
	}

	private void register(Encounter encounter)
	{
		for (String member : encounter.members)
		{
			byNpcName.put(member, encounter);
		}
	}

	/**
	 * @return the encounter this NPC takes part in, or null if it is not tracked
	 */
	Encounter encounterFor(NPC npc)
	{
		String name = npc.getName();
		return name == null ? null : byNpcName.get(name);
	}

	private static Set<String> singleton(String name)
	{
		return Collections.singleton(name);
	}

	private static Set<String> names(String... values)
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(values)));
	}
}

package com.bossfightlog;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * One completed kill.
 * <p>
 * A stripe down the left edge carries how the kill compared with the others, so a long list can be
 * skimmed for the good and bad ones without reading a single number. Colour is used for meaning
 * only: orange for the kill time and green or red for the comparison. The supporting figures
 * stay uniformly grey, so nothing competes with the two that carry the result.
 */
class FightCard extends JPanel
{
	private static final Font DPS_FONT = Fonts.monoBold(16f);
	private static final Font NAME_FONT = Fonts.regular(12f);
	private static final Font TIME_FONT = Fonts.monoBold(14f);
	/**
	 * The supporting line is the widest thing on a card and monospaced text is wider than
	 * proportional, so it takes a size down to survive five figure damage totals.
	 */
	private static final Font CAPTION_FONT = Fonts.mono(10f);

	/**
	 * The comparison is a headline number, not supporting detail, so it does not share the
	 * supporting line's size.
	 */
	private static final Font TREND_FONT = Fonts.monoBold(11f);
	private static final int STRIPE_WIDTH = 2;

	/**
	 * Usable width inside the panel once its scrollbar has taken its share.
	 */
	private static final int MAX_WIDTH = PluginPanel.PANEL_WIDTH - PluginPanel.SCROLLBAR_WIDTH;

	/**
	 * @param dpsTrend signed fraction against this boss's other kills, or null when there is
	 *                 nothing to compare against
	 */
	FightCard(BossFight fight, Double dpsTrend)
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(stripeBorder(stripeColor(dpsTrend)));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		add(buildHeader(fight), BorderLayout.NORTH);
		add(buildBody(fight, dpsTrend), BorderLayout.CENTER);

		setToolTipText(buildTooltip(fight, dpsTrend));
		installHover(this, stripeColor(dpsTrend));
	}

	private static CompoundBorder stripeBorder(Color stripe)
	{
		return new CompoundBorder(
			new MatteBorder(0, STRIPE_WIDTH, 0, 0, stripe),
			new EmptyBorder(5, 8, 5, 8));
	}

	/**
	 * Grey covers both a first kill and one that landed on the average: neither is a result worth
	 * colouring.
	 */
	private static Color stripeColor(Double dpsTrend)
	{
		if (dpsTrend == null || Math.abs(dpsTrend) < 0.01)
		{
			return ColorScheme.MEDIUM_GRAY_COLOR;
		}
		return dpsTrend > 0 ? Formats.TREND_UP : Formats.TREND_DOWN;
	}

	private static JPanel buildHeader(BossFight fight)
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);

		// Centre slot rather than west: west takes its full preferred width and prints over the
		// time on a long boss name, whereas centre takes what is left and truncates.
		JLabel name = new JLabel(fight.getBossName() + " (lvl-" + fight.getCombatLevel() + ")");
		name.setFont(NAME_FONT);
		name.setForeground(ColorScheme.TEXT_COLOR);
		name.setMinimumSize(new Dimension(0, name.getPreferredSize().height));

		JLabel time = new JLabel(Formats.duration(fight.getDurationSeconds()));
		time.setFont(TIME_FONT);
		time.setForeground(ColorScheme.BRAND_ORANGE);
		time.setBorder(new EmptyBorder(0, 6, 0, 0));

		header.add(name, BorderLayout.CENTER);
		header.add(time, BorderLayout.EAST);
		return header;
	}

	private static JPanel buildBody(BossFight fight, Double dpsTrend)
	{
		JPanel body = new JPanel(new BorderLayout());
		body.setOpaque(false);
		body.setBorder(new EmptyBorder(1, 0, 0, 0));

		JPanel rateRow = new JPanel(new BorderLayout());
		rateRow.setOpaque(false);

		String muted = Formats.hex(ColorScheme.MEDIUM_GRAY_COLOR);

		// A kill landed inside a single tick has no duration to divide by, so there is no rate to
		// show. Printing one would be inventing it.
		JLabel rate = new JLabel(fight.isDpsMeasurable()
			? "<html>" + Formats.dps(fight.getDps())
				+ " <font size='2' color='" + muted + "'>DPS</font></html>"
			: "<html><font color='" + muted + "'>instant kill</font></html>");
		rate.setFont(DPS_FONT);
		rate.setForeground(ColorScheme.TEXT_COLOR);

		JLabel trend = new JLabel(Formats.trendText(dpsTrend), SwingConstants.RIGHT);
		trend.setFont(TREND_FONT);
		trend.setForeground(stripeColor(dpsTrend));

		rateRow.add(rate, BorderLayout.CENTER);
		rateRow.add(trend, BorderLayout.EAST);

		JLabel detail = new JLabel("<html>"
			+ "<font color='" + muted + "'>" + Formats.number(fight.getDamageDealt()) + " dealt &middot; </font>"
			+ "<font color='" + muted + "'>" + Formats.number(fight.getDamageTaken()) + " taken</font>"
			+ "<font color='" + muted + "'> &middot; " + Formats.percent(fight.getAccuracy()) + "</font>"
			+ "</html>");
		detail.setFont(CAPTION_FONT);
		detail.setBorder(new EmptyBorder(1, 0, 0, 0));

		body.add(rateRow, BorderLayout.NORTH);
		body.add(detail, BorderLayout.CENTER);
		return body;
	}

	private static String buildTooltip(BossFight fight, Double dpsTrend)
	{
		String trend = dpsTrend == null
			? "First recorded kill of this boss"
			: Formats.percentSignedPrecise(dpsTrend) + " DPS against your other kills of this boss";

		return "<html>"
			+ "Max hit: " + fight.getMaxHit() + "<br>"
			+ "Hits landed: " + fight.getHits() + " of " + (fight.getHits() + fight.getMisses()) + "<br>"
			+ "Fight time: " + Formats.duration(fight.getDurationSeconds()) + " (idle time excluded)<br>"
			+ trend
			+ "</html>";
	}

	/**
	 * Highlights the whole card on hover. The listener goes on every descendant as well, otherwise
	 * moving the pointer onto a child label reads as leaving the card.
	 */
	private static void installHover(FightCard card, Color stripe)
	{
		MouseAdapter hover = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				card.setBackground(Formats.CARD_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				card.setBackground(Formats.CARD_COLOR);
			}
		};

		addRecursively(card, hover);
	}

	private static void addRecursively(Container container, MouseAdapter listener)
	{
		container.addMouseListener(listener);
		for (Component child : container.getComponents())
		{
			if (child instanceof Container)
			{
				addRecursively((Container) child, listener);
			}
			else
			{
				child.addMouseListener(listener);
			}
		}
	}

	/**
	 * The column this sits in is only ever as wide as the panel, so a long boss name must not be
	 * allowed to report a preferred width past it. Without this the widest card widens the whole
	 * column and every card loses its right hand edge.
	 */
	@Override
	public Dimension getPreferredSize()
	{
		Dimension size = super.getPreferredSize();
		return new Dimension(Math.min(size.width, MAX_WIDTH), size.height);
	}

	@Override
	public Dimension getMinimumSize()
	{
		Dimension size = super.getMinimumSize();
		return new Dimension(0, size.height);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.bossfightlog;

import com.google.gson.Gson;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSerializer;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Reads and writes recorded kills under {@code .runelite/boss-fight-log/}, one file per character.
 * <p>
 * All disk access runs on the shared executor rather than the client thread. Callbacks are handed
 * back on that executor thread, so callers are responsible for marshalling onto whichever thread
 * owns the data they are updating.
 */
@Slf4j
@Singleton
class FightStore
{
	/**
	 * Oldest kills are dropped past this point. Without a cap the file grows for as long as the
	 * plugin is installed.
	 */
	static final int MAX_FIGHTS = 1000;

	/**
	 * How many superseded copies to keep alongside the live file.
	 */
	private static final int MAX_BACKUPS = 5;
	private static final String BACKUP_SUFFIX = ".bak.json";
	private static final DateTimeFormatter BACKUP_STAMP = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final File directory;

	@Inject
	private FightStore(Gson gson, ScheduledExecutorService executor)
	{
		// Instant has no built-in Gson representation, so it is stored as epoch millis.
		this.gson = gson.newBuilder()
			.registerTypeAdapter(Instant.class,
				(JsonSerializer<Instant>) (src, type, ctx) -> new JsonPrimitive(src.toEpochMilli()))
			.registerTypeAdapter(Instant.class,
				(JsonDeserializer<Instant>) (json, type, ctx) -> Instant.ofEpochMilli(json.getAsLong()))
			.create();
		this.executor = executor;
		this.directory = new File(RuneLite.RUNELITE_DIR, "boss-fight-log");
	}

	void load(String character, Consumer<List<BossFight>> callback)
	{
		executor.execute(() -> {
			List<BossFight> fights = readFile(fileFor(character));
			callback.accept(fights);
		});
	}

	/**
	 * @param fights snapshot to persist; the caller must not mutate it afterwards
	 */
	void save(String character, List<BossFight> fights)
	{
		List<BossFight> snapshot = new ArrayList<>(fights);
		executor.execute(() -> writeFile(fileFor(character), snapshot));
	}

	/**
	 * Persists after copying whatever is on disk aside first. Used for destructive changes, so a
	 * mistaken clear costs a few clicks to undo rather than the entire history.
	 *
	 * @param fights snapshot to persist; the caller must not mutate it afterwards
	 */
	void saveWithBackup(String character, List<BossFight> fights)
	{
		List<BossFight> snapshot = new ArrayList<>(fights);
		// Both steps run in one task so the copy cannot be scheduled after the overwrite.
		executor.execute(() -> {
			File file = fileFor(character);
			backup(file);
			writeFile(file, snapshot);
		});
	}

	private void backup(File file)
	{
		if (!file.exists())
		{
			return;
		}

		try
		{
			String stamp = BACKUP_STAMP.format(LocalDateTime.now());
			File copy = new File(directory, file.getName().replace(".json", "") + "-" + stamp + BACKUP_SUFFIX);
			Files.copy(file.toPath(), copy.toPath(), StandardCopyOption.REPLACE_EXISTING);
			log.debug("Backed up fight history to {}", copy);
			prune(file.getName().replace(".json", ""));
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not back up fight history before overwriting {}", file, e);
		}
	}

	/**
	 * Keeps only the most recent backups, so the folder does not accumulate copies forever.
	 */
	private void prune(String prefix)
	{
		File[] backups = directory.listFiles((dir, name) ->
			name.startsWith(prefix + "-") && name.endsWith(BACKUP_SUFFIX));

		if (backups == null || backups.length <= MAX_BACKUPS)
		{
			return;
		}

		Arrays.sort(backups, Comparator.comparing(File::getName));
		for (int i = 0; i < backups.length - MAX_BACKUPS; i++)
		{
			if (!backups[i].delete())
			{
				log.debug("Could not remove old backup {}", backups[i]);
			}
		}
	}

	private List<BossFight> readFile(File file)
	{
		if (!file.exists())
		{
			return new ArrayList<>();
		}

		try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8))
		{
			BossFight[] fights = gson.fromJson(reader, BossFight[].class);
			return fights == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(fights));
		}
		catch (IOException | RuntimeException e)
		{
			// A corrupt or truncated file should cost the history, not the plugin.
			log.warn("Could not read fight history from {}, starting empty", file, e);
			return new ArrayList<>();
		}
	}

	private void writeFile(File file, List<BossFight> fights)
	{
		try
		{
			Files.createDirectories(directory.toPath());
			try (Writer writer = Files.newBufferedWriter(file.toPath(), StandardCharsets.UTF_8))
			{
				gson.toJson(fights.toArray(new BossFight[0]), BossFight[].class, writer);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not write fight history to {}", file, e);
		}
	}

	/**
	 * Display names allow spaces and are case insensitive in game, so they are folded to a stable
	 * lower case form and stripped of anything that is awkward in a filename.
	 */
	private File fileFor(String character)
	{
		String safe = character.replace('\u00A0', ' ')
			.toLowerCase()
			.trim()
			.replaceAll("[^a-z0-9]+", "_");

		if (safe.isEmpty())
		{
			safe = "unknown";
		}

		return new File(directory, safe + ".json");
	}

	static List<BossFight> capped(List<BossFight> fights)
	{
		if (fights.size() <= MAX_FIGHTS)
		{
			return fights;
		}
		return new ArrayList<>(fights.subList(fights.size() - MAX_FIGHTS, fights.size()));
	}
}

package com.bossfightlog;

import java.time.Instant;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;

/**
 * Accumulates combat statistics for the boss currently being fought, and emits a {@link BossFight}
 * once the boss dies.
 * <p>
 * Only one fight is tracked at a time. Damage taken cannot be attributed to a particular attacker,
 * so a single active fight is the only way to assign it unambiguously; bosses are close enough to
 * single-target that this holds in practice.
 * <p>
 * Timing is measured in game ticks rather than wall clock, so it does not drift with frame rate or
 * latency. Gaps longer than the configured idle timeout are deducted entirely, which keeps banking
 * and travel out of the DPS figure. The timeout sits far above attack speed on purpose: a couple of
 * missed attack cycles is ordinary combat, and deducting those would shorten fights and inflate
 * every rate derived from them.
 */
@Slf4j
@Singleton
public class FightTracker
{
	/**
	 * Drop a fight that has seen no activity for this long. Prevents a boss that was walked away
	 * from, or that despawned unseen, from being credited to the next kill.
	 */
	private static final int ABANDON_AFTER_TICKS = 200;

	/**
	 * How long a despawned boss has to reappear before its fight is written off. Long enough to
	 * cover a phase transition, short enough that a boss which genuinely reset is not credited to
	 * the next kill.
	 */
	private static final int RESUME_GRACE_TICKS = 20;

	private final Client client;
	private final BossFightLogConfig config;
	private final BossRegistry bossRegistry;

	private FightState active;

	/**
	 * A fight whose boss has despawned, held in case the same boss returns.
	 */
	private FightState parked;
	private int parkedAtTick;
	private Consumer<BossFight> fightListener = fight -> {
	};

	@Inject
	private FightTracker(Client client, BossFightLogConfig config, BossRegistry bossRegistry)
	{
		this.client = client;
		this.config = config;
		this.bossRegistry = bossRegistry;
	}

	public void setFightListener(Consumer<BossFight> fightListener)
	{
		this.fightListener = fightListener;
	}

	public void reset()
	{
		active = null;
		parked = null;
	}

	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		Hitsplat hitsplat = event.getHitsplat();
		int type = hitsplat.getHitsplatType();
		int amount = hitsplat.getAmount();
		int tick = client.getTickCount();

		if (actor instanceof NPC)
		{
			boolean dealt = Hitsplats.isDamageDealtByPlayer(type);
			if (!dealt && !Hitsplats.isMissByPlayer(type))
			{
				return;
			}

			FightState fight = fightFor((NPC) actor, tick);
			if (fight == null)
			{
				return;
			}

			registerActivity(fight, tick);

			if (dealt && amount > 0)
			{
				fight.hits++;
				fight.damageDealt += amount;
				fight.maxHit = Math.max(fight.maxHit, amount);
			}
			else
			{
				fight.misses++;
			}
		}
		else if (active != null && actor == client.getLocalPlayer() && Hitsplats.isDamageTaken(type))
		{
			// Taking damage deliberately does not count as activity: tanking without attacking is
			// idle time as far as DPS is concerned.
			active.damageTaken += amount;
		}
	}

	public void onActorDeath(ActorDeath event)
	{
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();

		if (active != null && active.liveMembers.remove(npc))
		{
			// A paired encounter is only over once both halves are down.
			if (active.liveMembers.isEmpty())
			{
				complete(client.getTickCount());
			}
			return;
		}

		// Death normally arrives before the despawn, but if the order is ever reversed the fight
		// would already be parked and the kill would be thrown away when the grace period expired.
		if (parked != null && parked.encounter == bossRegistry.encounterFor(npc))
		{
			active = parked;
			parked = null;
			complete(client.getTickCount());
		}
	}

	/**
	 * A boss that changes form is reported as the same {@link NPC} object with a new id, so the
	 * fight carries on untouched. Logged only to establish which bosses behave this way and which
	 * despawn instead.
	 */
	public void onNpcChanged(NpcChanged event)
	{
		if (active != null && active.liveMembers.contains(event.getNpc()))
		{
			log.debug("{} transformed in place, fight continues", active.name);
		}
	}

	public void onNpcDespawned(NpcDespawned event)
	{
		if (active == null || !active.liveMembers.remove(event.getNpc()))
		{
			return;
		}

		if (!active.liveMembers.isEmpty())
		{
			// The other half of a pair is still up, so the fight carries on.
			return;
		}

		// A despawn is not necessarily the end: a phased boss may vanish and return as a fresh
		// NPC. The fight is parked rather than discarded, and resumes if the same encounter is
		// engaged again shortly afterwards.
		parked = active;
		parkedAtTick = client.getTickCount();
		active = null;
		log.debug("Parked fight against {} after despawn", parked.name);
	}

	public void onGameTick()
	{
		int tick = client.getTickCount();

		if (active != null && tick - active.lastActivityTick > ABANDON_AFTER_TICKS)
		{
			log.debug("Abandoning stale fight against {}", active.name);
			active = null;
		}

		if (parked != null && tick - parkedAtTick > RESUME_GRACE_TICKS)
		{
			log.debug("Discarding parked fight against {}: did not return", parked.name);
			parked = null;
		}
	}

	private FightState fightFor(NPC npc, int tick)
	{
		BossRegistry.Encounter encounter = bossRegistry.encounterFor(npc);
		if (encounter == null)
		{
			return null;
		}

		if (active != null)
		{
			if (active.encounter != encounter)
			{
				return null;
			}
			track(active, npc, encounter);
			return active;
		}

		if (parked != null && parked.encounter == encounter)
		{
			// Same encounter back again within the grace period: carry on the fight it was already
			// in rather than starting a second one. The time it was away is deducted as idle by the
			// activity bookkeeping, so vanishing does not flatter the DPS.
			active = parked;
			parked = null;
			track(active, npc, encounter);
			log.debug("Resumed fight against {}", active.name);
			return active;
		}

		// Hitting an add first does not open a fight; the boss itself has to be engaged.
		if (!encounter.isMember(npc.getName()))
		{
			return null;
		}

		active = new FightState(encounter, npc, tick);
		log.debug("Started fight against {}", active.name);
		return active;
	}

	/**
	 * Records a member as part of the fight so its death is what ends the encounter. Adds are
	 * deliberately not tracked here: their damage counts, but killing one proves nothing.
	 */
	private static void track(FightState fight, NPC npc, BossRegistry.Encounter encounter)
	{
		if (encounter.isMember(npc.getName()))
		{
			fight.liveMembers.add(npc);
		}
	}

	private void registerActivity(FightState fight, int tick)
	{
		int gap = tick - fight.lastActivityTick;
		if (gap > idleTimeoutTicks())
		{
			fight.idleTicks += gap;
			fight.idleGaps++;
			// Logged individually because a deduction is the one thing that makes the recorded
			// time disagree with the clock, and the size of each gap says what caused it.
			log.debug("Deducted a {} tick gap ({}s) from {}",
				gap, String.format("%.1f", gap * BossFight.SECONDS_PER_TICK), fight.name);
		}
		fight.lastActivityTick = tick;
	}

	private void complete(int tick)
	{
		FightState fight = active;
		active = null;

		// A boss killed within a single tick took no measurable time. Clamping that to one tick
		// would invent 0.6 seconds to divide by and report a DPS that was never measured.
		int duration = Math.max(0, tick - fight.startTick - fight.idleTicks);

		BossFight result = new BossFight(
			fight.name,
			fight.combatLevel,
			fight.damageDealt,
			fight.damageTaken,
			fight.hits,
			fight.misses,
			fight.maxHit,
			duration,
			Instant.now());

		log.debug("Fight against {} spanned {} ticks, of which {} deducted across {} gaps",
			fight.name, tick - fight.startTick, fight.idleTicks, fight.idleGaps);
		log.debug("Completed fight: {}", result);
		fightListener.accept(result);
	}

	private int idleTimeoutTicks()
	{
		return Math.max(1, config.idleTimeoutTicks());
	}

	private static final class FightState
	{
		private final BossRegistry.Encounter encounter;
		private final String name;
		private final int combatLevel;
		private final int startTick;

		/**
		 * Members engaged and not yet dead. The encounter ends when this empties, which is what
		 * makes a paired boss one kill rather than two half fights.
		 */
		private final Set<NPC> liveMembers = new HashSet<>();

		private int lastActivityTick;
		private int idleTicks;
		private int idleGaps;
		private int damageDealt;
		private int damageTaken;
		private int hits;
		private int misses;
		private int maxHit;

		private FightState(BossRegistry.Encounter encounter, NPC first, int startTick)
		{
			this.encounter = encounter;
			this.name = encounter.getName();
			this.combatLevel = first.getCombatLevel();
			this.startTick = startTick;
			this.lastActivityTick = startTick;
			this.liveMembers.add(first);
		}
	}
}

package com.bossfightlog;

import java.awt.Font;
import java.awt.GraphicsEnvironment;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.ui.FontManager;

/**
 * Picks the clearest interface font available on the machine.
 * <p>
 * RuneLite's default font is Java's logical "Dialog" family, which the runtime maps to whatever it
 * likes: usually Microsoft Sans Serif or Arial, neither of which was drawn for small interface
 * text. The RuneScape fonts are pixel faces built for one size, so they blur when scaled to the
 * sizes the summary figures need.
 * <p>
 * Rather than bundle a typeface and carry it in the jar, this resolves the first genuinely good
 * face already installed and falls back through the list, ending at whatever RuneLite would have
 * used anyway. The panel looks native on each platform instead of identical on all of them, which
 * for a side panel inside someone else's client is the better trade.
 */
final class Fonts
{
	/**
	 * In preference order: Segoe UI ships with Windows, Inter and Roboto are common developer
	 * installs, and the last two are the usual Linux and general fallbacks.
	 */
	private static final String[] PREFERRED = {
		"Segoe UI",
		"Inter",
		"Roboto",
		"Noto Sans",
		"DejaVu Sans",
	};

	/**
	 * Monospaced faces, in preference order. Cascadia and Consolas ship with Windows, the rest
	 * cover the usual Linux and Mac installs, and Java's logical "Monospaced" is the backstop.
	 */
	private static final String[] PREFERRED_MONO = {
		"Cascadia Mono",
		"Consolas",
		"JetBrains Mono",
		"DejaVu Sans Mono",
		"Menlo",
	};

	private static final String MONO_FAMILY;
	private static final String MONO_SEMIBOLD_FAMILY;

	private static final String FAMILY;
	private static final String SEMIBOLD_FAMILY;

	static
	{
		Set<String> available = new HashSet<>(Arrays.asList(
			GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames()));

		String chosen = null;
		for (String candidate : PREFERRED)
		{
			if (available.contains(candidate))
			{
				chosen = candidate;
				break;
			}
		}

		FAMILY = chosen;
		// A true semibold reads better than synthetic bold for figures, where heavy strokes close
		// up the counters at small sizes.
		SEMIBOLD_FAMILY = chosen != null && available.contains(chosen + " Semibold")
			? chosen + " Semibold"
			: null;

		String mono = null;
		for (String candidate : PREFERRED_MONO)
		{
			if (available.contains(candidate))
			{
				mono = candidate;
				break;
			}
		}
		MONO_FAMILY = mono;
		MONO_SEMIBOLD_FAMILY = mono != null && available.contains(mono + " SemiBold")
			? mono + " SemiBold"
			: null;
	}

	private Fonts()
	{
	}

	/**
	 * Small capitals used as captions need a little tracking, or the letters crowd and read as
	 * shrunken body text rather than a label.
	 */
	static Font caption(float size)
	{
		java.util.Map<java.awt.font.TextAttribute, Object> attributes = new java.util.HashMap<>();
		attributes.put(java.awt.font.TextAttribute.TRACKING, 0.08f);
		return regular(size).deriveFont(attributes);
	}

	static Font regular(float size)
	{
		return FAMILY == null
			? FontManager.getDefaultFont().deriveFont(size)
			: new Font(FAMILY, Font.PLAIN, Math.round(size));
	}

	static Font bold(float size)
	{
		if (SEMIBOLD_FAMILY != null)
		{
			return new Font(SEMIBOLD_FAMILY, Font.PLAIN, Math.round(size));
		}
		return FAMILY == null
			? FontManager.getDefaultBoldFont().deriveFont(size)
			: new Font(FAMILY, Font.BOLD, Math.round(size));
	}

	/**
	 * Monospaced, for figures. Every digit occupies the same width, so a column of numbers lines
	 * up on its decimal without any layout doing the work.
	 */
	static Font mono(float size)
	{
		return MONO_FAMILY == null
			? new Font(Font.MONOSPACED, Font.PLAIN, Math.round(size))
			: new Font(MONO_FAMILY, Font.PLAIN, Math.round(size));
	}

	static Font monoBold(float size)
	{
		if (MONO_SEMIBOLD_FAMILY != null)
		{
			return new Font(MONO_SEMIBOLD_FAMILY, Font.PLAIN, Math.round(size));
		}
		return MONO_FAMILY == null
			? new Font(Font.MONOSPACED, Font.BOLD, Math.round(size))
			: new Font(MONO_FAMILY, Font.BOLD, Math.round(size));
	}

	/**
	 * @return the resolved family, for logging at startup
	 */
	static String describe()
	{
		String sans = FAMILY == null ? "RuneLite default" : FAMILY;
		String monoName = MONO_FAMILY == null ? "logical monospaced" : MONO_FAMILY;
		return sans + " + " + monoName;
	}
}

package com.bossfightlog;

import java.awt.Color;

/**
 * Display formatting shared by the panel widgets.
 */
final class Formats
{
	/**
	 * Differences smaller than this are rounding rather than performance.
	 */
	private static final double TREND_NOISE_THRESHOLD = 0.01d;

	/**
	 * Sampled from the reference design. RuneLite's progress colours are pitched for a bar that
	 * has to read at a glance across the client; on a dense panel of figures they shout.
	 */
	static final Color TREND_UP = new Color(0x4DBB5F);
	static final Color TREND_DOWN = new Color(0xE04B4B);

	/**
	 * Card fill, and the fill while hovered.
	 * <p>
	 * RuneLite's hover colour doubles the luminance of a card, from grey 30 to grey 60, which is
	 * built for list rows on a lighter background and reads as a flash here. Eight points is enough
	 * to show which card the pointer is on without the panel lighting up under it.
	 */
	static final Color CARD_COLOR = new Color(30, 30, 30);
	static final Color CARD_HOVER_COLOR = new Color(38, 38, 38);

	private Formats()
	{
	}

	/**
	 * Renders a colour as a CSS hex string, for use inside HTML labels.
	 */
	static String hex(Color color)
	{
		return String.format("#%06x", color.getRGB() & 0xFFFFFF);
	}

	/**
	 * Formats a duration as m:ss, or h:mm:ss once it runs past an hour.
	 */
	static String duration(double seconds)
	{
		int total = (int) Math.round(seconds);
		int hours = total / 3600;
		int minutes = (total % 3600) / 60;
		int secs = total % 60;

		return hours > 0
			? String.format("%d:%02d:%02d", hours, minutes, secs)
			: String.format("%d:%02d", minutes, secs);
	}

	static String dps(double dps)
	{
		return String.format("%.1f", dps);
	}

	/**
	 * @param fraction a value in the range 0..1
	 */
	static String percent(double fraction)
	{
		return String.format("%.0f%%", fraction * 100);
	}

	static String number(int value)
	{
		return String.format("%,d", value);
	}

	/**
	 * @param fraction a signed value, where 0.12 reads as +12%
	 */
	static String percentSigned(double fraction)
	{
		return String.format("%+.0f%%", fraction * 100);
	}

	/**
	 * As {@link #percentSigned}, but keeping a decimal place. Used where rounding a small
	 * difference to a signed zero would be more confusing than the extra digit.
	 */
	static String percentSignedPrecise(double fraction)
	{
		return String.format("%+.1f%%", fraction * 100);
	}

	/**
	 * The trend as plain text for a standalone label, where the colour is carried by the component
	 * rather than by markup. Empty when there is no baseline; "on par" inside the noise threshold,
	 * because a blank there would look identical to a first kill.
	 */
	static String trendText(Double fraction)
	{
		if (fraction == null)
		{
			return "";
		}
		return Math.abs(fraction) < TREND_NOISE_THRESHOLD ? "on par" : percentSigned(fraction);
	}
}

package com.bossfightlog;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * One boss's aggregate row in the grouped view, which expands on click to reveal the individual
 * kills behind it.
 */
class GroupCard extends JPanel
{
	private static final java.awt.Font NAME_FONT = Fonts.regular(12f);
	private static final java.awt.Font COUNT_FONT = Fonts.monoBold(14f);
	private static final java.awt.Font DPS_FONT = Fonts.monoBold(16f);
	private static final java.awt.Font CAPTION_FONT = Fonts.mono(10f);

	/**
	 * A neutral stripe of the same width as a kill card's, so the two views line up down their
	 * left edge. It carries no colour because a group has nothing to be compared against.
	 */
	private static final int STRIPE_WIDTH = 2;
	private static final int MAX_WIDTH = PluginPanel.PANEL_WIDTH - PluginPanel.SCROLLBAR_WIDTH;

	private final BossGroup group;
	private final List<BossFight> allFights;
	private final JPanel summaryRow = new JPanel(new BorderLayout());
	private final JPanel expansion = new JPanel();
	private final JLabel killCount = new JLabel();

	private boolean expanded;
	private boolean built;

	GroupCard(BossGroup group, List<BossFight> allFights)
	{
		this.group = group;
		this.allFights = allFights;

		setLayout(new BorderLayout());
		setBackground(Formats.CARD_COLOR);
		setBorder(new CompoundBorder(
			new MatteBorder(0, STRIPE_WIDTH, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(5, 8, 5, 8)));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setCursor(new Cursor(Cursor.HAND_CURSOR));

		expansion.setLayout(new BoxLayout(expansion, BoxLayout.Y_AXIS));
		expansion.setOpaque(false);
		expansion.setBorder(new EmptyBorder(6, 0, 0, 0));
		expansion.setVisible(false);

		buildSummary();
		add(summaryRow, BorderLayout.NORTH);
		add(expansion, BorderLayout.CENTER);

		setToolTipText("Click to " + "show each kill");
		installClickAndHover();
	}

	private void buildSummary()
	{
		summaryRow.setOpaque(false);

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);

		// Centre slot so a long boss name truncates rather than printing over the kill count.
		JLabel name = new JLabel(group.getBossName() + " (lvl-" + group.getCombatLevel() + ")");
		name.setFont(NAME_FONT);
		name.setForeground(ColorScheme.TEXT_COLOR);
		name.setMinimumSize(new Dimension(0, name.getPreferredSize().height));

		killCount.setText(group.getKills() + (group.getKills() == 1 ? " kill" : " kills"));
		killCount.setFont(COUNT_FONT);
		killCount.setForeground(ColorScheme.BRAND_ORANGE);
		killCount.setBorder(new EmptyBorder(0, 6, 0, 0));

		header.add(name, BorderLayout.CENTER);
		header.add(killCount, BorderLayout.EAST);

		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		body.setBorder(new EmptyBorder(1, 0, 0, 0));

		String muted = Formats.hex(ColorScheme.MEDIUM_GRAY_COLOR);

		JLabel dps = new JLabel("<html>" + Formats.dps(group.getAverageDps())
			+ " <font color='" + muted + "'>AVG DPS</font></html>");
		dps.setFont(DPS_FONT);
		dps.setForeground(ColorScheme.TEXT_COLOR);
		dps.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel detail = new JLabel("<html><font color='" + muted + "'>"
			+ "avg " + Formats.duration(group.getAverageSeconds())
			+ " &middot; best " + Formats.duration(group.getBestSeconds())
			+ " &middot; " + Formats.percent(group.getAccuracy())
			+ "</font></html>");
		detail.setFont(CAPTION_FONT);
		detail.setAlignmentX(Component.LEFT_ALIGNMENT);

		body.add(dps);
		body.add(detail);

		summaryRow.add(header, BorderLayout.NORTH);
		summaryRow.add(body, BorderLayout.CENTER);
	}

	private void toggle()
	{
		expanded = !expanded;

		// Individual cards are built the first time they are needed, so a long history does not pay
		// for rows nobody opens.
		if (expanded && !built)
		{
			for (BossFight fight : group.getFightsNewestFirst())
			{
				FightCard card = new FightCard(fight, BossGroup.dpsTrend(fight, allFights));
				card.setBackground(ColorScheme.DARK_GRAY_COLOR);
				card.setBorder(new EmptyBorder(5, 6, 5, 6));
				JPanel spacer = new JPanel(new BorderLayout());
				spacer.setOpaque(false);
				spacer.setBorder(new EmptyBorder(0, 0, 3, 0));
				spacer.add(card, BorderLayout.CENTER);
				spacer.setMaximumSize(new Dimension(Integer.MAX_VALUE, spacer.getPreferredSize().height));
				expansion.add(spacer);
			}
			built = true;
		}

		expansion.setVisible(expanded);
		setToolTipText("Click to " + (expanded ? "hide" : "show") + " each kill");

		revalidate();
		repaint();
	}

	private void installClickAndHover()
	{
		MouseAdapter listener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggle();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				setBackground(Formats.CARD_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setBackground(Formats.CARD_COLOR);
			}
		};

		// Only the summary row toggles: clicks on an expanded kill card should not collapse it.
		addMouseListener(listener);
		addRecursively(summaryRow, listener);
	}

	private static void addRecursively(Container container, MouseAdapter listener)
	{
		container.addMouseListener(listener);
		for (Component child : container.getComponents())
		{
			if (child instanceof Container)
			{
				addRecursively((Container) child, listener);
			}
			else
			{
				child.addMouseListener(listener);
			}
		}
	}

	/**
	 * The column this sits in is only ever as wide as the panel, so a long boss name must not be
	 * allowed to report a preferred width past it. Without this the widest card widens the whole
	 * column and every card loses its right hand edge.
	 */
	@Override
	public Dimension getPreferredSize()
	{
		Dimension size = super.getPreferredSize();
		return new Dimension(Math.min(size.width, MAX_WIDTH), size.height);
	}

	@Override
	public Dimension getMinimumSize()
	{
		Dimension size = super.getMinimumSize();
		return new Dimension(0, size.height);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.bossfightlog;

import net.runelite.api.HitsplatID;

/**
 * Classifies raw hitsplat type ids.
 * <p>
 * {@link net.runelite.api.Hitsplat#isMine()} is deliberately not used here. It reports true for
 * BLOCK_ME and for the POISE types as well as for real damage, and this plugin needs those three
 * cases kept apart: a block is a miss for accuracy purposes, and poise is a separate stagger meter
 * rather than hitpoint damage, so folding it into damage dealt would inflate DPS.
 */
final class Hitsplats
{
	private Hitsplats()
	{
	}

	/**
	 * Hitpoint damage dealt by the local player. Excludes poise, which is not hitpoint damage.
	 */
	static boolean isDamageDealtByPlayer(int type)
	{
		switch (type)
		{
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
				return true;
			default:
				return false;
		}
	}

	/**
	 * A splash or block from the local player, which counts against accuracy.
	 */
	static boolean isMissByPlayer(int type)
	{
		return type == HitsplatID.BLOCK_ME;
	}

	/**
	 * Damage landing on the local player, from any source.
	 * <p>
	 * Callers must already have established that the hitsplat is on the local player, which is why
	 * both the ME and OTHER damage families are accepted. Heals, prayer and sanity drain, poise and
	 * blocks are all excluded.
	 */
	static boolean isDamageTaken(int type)
	{
		switch (type)
		{
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.POISON:
			case HitsplatID.VENOM:
			case HitsplatID.BURN:
			case HitsplatID.BLEED:
				return true;
			default:
				return false;
		}
	}
}

package com.bossfightlog;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Color;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.Collections;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * Totals across every recorded kill, as a grid of stat tiles.
 * <p>
 * Each tile is a figure over a caption rather than a label beside a value, so the numbers line up
 * as a block and the eye lands on them first. The RuneScape fonts are bitmaps and cannot be scaled,
 * so the headline figures use the default font, which is a real outline font.
 */
class SummaryPanel extends JPanel
{
	private static final Font VALUE_FONT = Fonts.monoBold(17f);
	private static final Font CAPTION_FONT = Fonts.caption(10f);

	/**
	 * Hairline rules between tiles. The grid draws them by letting its background show through
	 * one pixel gaps, so this is the grid fill rather than a border colour.
	 */
	private static final Color RULE_COLOR = ColorScheme.MEDIUM_GRAY_COLOR.darker();

	private final JLabel heading = new JLabel("SESSION");
	private final JLabel headingValue = new JLabel();
	private final JPanel grid = new JPanel(new GridLayout(0, 2, 1, 1));

	SummaryPanel()
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// No right edge: the panel is already bounded there by the scrollbar, and no inset, so the
		// rules between tiles run into the border instead of stopping a pixel short of it.
		setBorder(new MatteBorder(1, 1, 1, 0, RULE_COLOR));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		// The gap colour shows through as hairline rules between tiles.
		grid.setBackground(RULE_COLOR);

		heading.setFont(CAPTION_FONT);
		heading.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		headingValue.setFont(CAPTION_FONT);
		headingValue.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		headingValue.setHorizontalAlignment(SwingConstants.RIGHT);

		JPanel headingRow = new JPanel(new BorderLayout());
		headingRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		headingRow.setBorder(new CompoundBorder(
			new MatteBorder(0, 0, 1, 0, RULE_COLOR),
			new EmptyBorder(6, 9, 6, 8)));
		headingRow.add(heading, BorderLayout.WEST);
		headingRow.add(headingValue, BorderLayout.EAST);

		add(headingRow, BorderLayout.NORTH);
		add(grid, BorderLayout.CENTER);


		update(Collections.emptyList());
	}

	void update(List<BossFight> fights)
	{
		grid.removeAll();

		if (fights.isEmpty())
		{
			grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			JLabel empty = new JLabel("No kills recorded yet", SwingConstants.CENTER);
			empty.setFont(CAPTION_FONT);
			empty.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			headingValue.setText("");
			grid.add(empty);
			revalidateAll();
			return;
		}

		grid.setBackground(RULE_COLOR);

		int kills = fights.size();
		int timedKills = 0;
		int totalDamage = 0;
		int totalTaken = 0;
		int totalHits = 0;
		int totalAttempts = 0;
		int totalTicks = 0;
		double bestDps = 0;
		double bestTime = Double.MAX_VALUE;

		for (BossFight fight : fights)
		{
			totalTaken += fight.getDamageTaken();
			totalHits += fight.getHits();
			totalAttempts += fight.getHits() + fight.getMisses();
			totalDamage += fight.getDamageDealt();

			// Kills landed inside a single tick have damage but no duration. They are counted as
			// kills, but contribute to no figure that divides one by the other.
			if (!fight.isDpsMeasurable())
			{
				continue;
			}

			timedKills++;
			totalTicks += fight.getDurationTicks();
			bestDps = Math.max(bestDps, fight.getDps());
			bestTime = Math.min(bestTime, fight.getDurationSeconds());
		}

		double timedSeconds = totalTicks * BossFight.SECONDS_PER_TICK;
		double timedDamage = 0;
		for (BossFight fight : fights)
		{
			if (fight.isDpsMeasurable())
			{
				timedDamage += fight.getDamageDealt();
			}
		}

		// Overall DPS is total damage over total time rather than the mean of each kill's DPS, so a
		// long fight counts for more than a short one.
		double overallDps = timedSeconds > 0 ? timedDamage / timedSeconds : 0;
		double accuracy = totalAttempts > 0 ? (double) totalHits / totalAttempts : 0;

		headingValue.setText(Formats.duration(timedSeconds) + " total");

		addTile(Formats.dps(overallDps), "AVG DPS");
		addTile(timedKills > 0 ? Formats.duration(timedSeconds / timedKills) : "—", "AVG KILL");
		addTile(timedKills > 0 ? Formats.dps(bestDps) : "—", "BEST DPS");
		addTile(bestTime == Double.MAX_VALUE ? "—" : Formats.duration(bestTime), "BEST KILL");
		addTile(Formats.number(totalDamage), "DMG DEALT");
		addTile(Formats.number(totalTaken), "DMG TAKEN");
		addTile(Formats.percent(accuracy), "ACCURACY");
		addTile(Formats.number(kills), "KILLS");

		revalidateAll();
	}

	/**
	 * Total fight time across kills that had a measurable duration.
	 */
	static double totalSeconds(java.util.List<BossFight> fights)
	{
		int ticks = 0;
		for (BossFight fight : fights)
		{
			if (fight.isDpsMeasurable())
			{
				ticks += fight.getDurationTicks();
			}
		}
		return ticks * BossFight.SECONDS_PER_TICK;
	}

	private void addTile(String value, String caption)
	{
		JPanel tile = new JPanel();
		tile.setLayout(new BoxLayout(tile, BoxLayout.Y_AXIS));
		tile.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		tile.setBorder(new EmptyBorder(8, 9, 8, 6));

		JLabel valueLabel = new JLabel(value);
		valueLabel.setFont(VALUE_FONT);
		valueLabel.setForeground(ColorScheme.TEXT_COLOR);
		valueLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel captionLabel = new JLabel(caption);
		captionLabel.setFont(CAPTION_FONT);
		captionLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		captionLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		tile.add(valueLabel);
		tile.add(captionLabel);
		grid.add(tile);
	}

	private void revalidateAll()
	{
		grid.revalidate();
		grid.repaint();
		revalidate();
		repaint();
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

